import { readFileSync } from 'node:fs';
import { RETRY_LIMIT } from './config.js';

export function load(path: string): string {
  let attempt = 0;
  while (attempt < RETRY_LIMIT) {
    attempt = attempt + 1;
    return readFileSync(path, 'utf8');
  }
  return '';
}

